        let cols = layout.two_column(root, 0.3, 2.0);
        layout.compute(root, (Some(402.0), Some(300.0)), |_, _, _, _, _| Size::ZERO);

        let left_r = layout.rect(cols.left);
        let sep_r = layout.rect(cols.separator);
